-- Scoped aggregate reads and lazy maintenance; expiration is always checked during entitlement queries.
create or replace function public.mvp_metrics(p_user uuid) returns jsonb language sql stable security definer set search_path=public as $$
select jsonb_build_object('users',case when mvp_is_admin(p_user) then (select count(*) from user_profiles) else 0 end,'licenses',(select count(*) from licenses where mvp_is_admin(p_user) or creator_id=p_user),'active',(select count(*) from licenses l where (mvp_is_admin(p_user) or l.creator_id=p_user) and l.status in ('active','redeemed') and exists(select 1 from license_activations a where a.license_id=l.id and (a.expires_at is null or a.expires_at>now()))),'banned',(select count(*) from licenses where (mvp_is_admin(p_user) or creator_id=p_user) and status='banned'),'expired',(select count(*) from licenses where (mvp_is_admin(p_user) or creator_id=p_user) and status='expired'),'unusedUsers',case when mvp_is_admin(p_user) then (select count(*) from user_profiles u where not exists(select 1 from license_activations where user_id=u.id)) else 0 end);$$;
create or replace function public.mvp_maintain(p_user uuid) returns void language plpgsql security definer set search_path=public as $$declare l licenses; begin
 insert into xp_accounts(user_id) values(p_user) on conflict do nothing;
 insert into notifications(user_id,title,body,event_key) values(p_user,'Welcome to MVP Store','Your orders, product access and updates will appear here.','welcome') on conflict do nothing;
 update subscriptions set status='expired' where user_id=p_user and status='active' and expires_at<=now();
 for l in select x.* from licenses x join reseller_access r on r.id=x.reseller_access_id where x.status not in ('revoked','expired') and (r.user_id=p_user or mvp_is_admin(p_user)) and (case when r.status='active' then r.ends_at+interval '15 days' else coalesce(r.grace_until,r.updated_at+interval '15 days') end)<=now() for update of x loop
 update licenses set status='revoked' where id=l.id;
 insert into audit_logs(action,entity_id,detail) values('reseller.grace.auto_revocation',l.id,jsonb_build_object('policy','15-day grace','accessId',l.reseller_access_id)); end loop;
 insert into notifications(user_id,title,body,event_key) select p_user,'Subscription reminder',p.name||' expires within 7 days.','expiry:'||a.id||':'||current_date from license_activations a join products p on p.id=a.product_id where a.user_id=p_user and a.expires_at>now() and a.expires_at<=now()+interval '7 days' on conflict do nothing;
end;$$;
create or replace function public.mvp_analytics(p_user uuid,p_days integer default 7) returns jsonb language sql stable security definer set search_path=public as $$
with days as (select generate_series(date_trunc('day',now())-(greatest(1,least(p_days,90))-1)*interval '1 day',date_trunc('day',now()),interval '1 day') as d), points as (select to_char(d,'Mon DD') as date, (select count(*) from licenses where created_at>=d and created_at<d+interval '1 day' and (mvp_is_admin(p_user) or creator_id=p_user)) as licenses, (select count(*) from orders where created_at>=d and created_at<d+interval '1 day' and (mvp_is_admin(p_user) or user_id=p_user)) as orders, (select count(distinct a.user_id) from license_activations a join licenses l on l.id=a.license_id where a.activated_at>=d and a.activated_at<d+interval '1 day' and (mvp_is_admin(p_user) or l.creator_id=p_user)) as users from days order by d) select coalesce(jsonb_agg(to_jsonb(points)),'[]'::jsonb) from points;$$;
-- Private tables intentionally have no browser grants. Own-row SELECT policies document future safe read scopes.
do $$declare t text; begin foreach t in array array['orders','subscriptions','xp_accounts','xp_claims','notifications','feedback','feedback_replies','feedback_likes','reseller_access','activity_events','contact_messages'] loop if not exists(select 1 from pg_policies where tablename=t and policyname='authenticated_select_own') then execute format('create policy authenticated_select_own on public.%I for select to authenticated using (user_id=auth.uid())',t); end if; end loop; end;$$;
revoke all on function public.mvp_metrics(uuid),public.mvp_maintain(uuid),public.mvp_analytics(uuid,integer) from public,anon,authenticated;
grant execute on function public.mvp_metrics(uuid),public.mvp_maintain(uuid),public.mvp_analytics(uuid,integer) to service_role;
revoke update,delete,truncate on public.audit_logs from anon,authenticated,service_role;
